from math import comb
a = int(input())
for i in range(a):
	N = int(input())
	matche = comb(N, 2)
	win = matche / N
	ans = []
	if win != int(win):
		print('NO')
		continue
	print('YES')
	for k in range(N):
		list = []
		for j in range(N):
			list.append(0)
		ans.append(list)
		list = []
	for k in range(N):
		temp = win
		index = 0
		while temp != 0:
			if index + 1 != k + 1 and ans[k][index] != 'set':
				ans[k][index] = 1
				ans[index][k] = 'set'
				temp -= 1
			index += 1
	for k in ans:
		for j in k:
			if j == 'set':
				print(0, end='')
			else:
				print(j, end='')
		print()
